<template>
  <div class="layout-px-spacing">  
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item"><a href="javascript:;">Assets</a></li>
              <li class="breadcrumb-item active" aria-current="page"><span>Fuel Cards</span></li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>   

    <div class="d-flex mb-2">
      <div class="flex-grow-1 text-center">
        <div v-if="selectedProject">
          <h5 class="m-0">FUEL MANAGEMENT FOR {{selectedProject?.short_name}}  ({{ selectedBudget?.name }})</h5>
        </div>
        <div v-else>
          <h5 class="m-0">FUEL MANAGEMENT</h5>
        </div>
      </div>
    </div>

    <div class="d-flex justify-content-center align-items-center gap-3 mt-2 mb-4">
      <button 
        v-if="total_transactions > 0"
        class="btn btn-secondary text-white ms-4" 
        @click.stop="ShowAssetDiv = !ShowAssetDiv"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" fill="currentColor" class="bi bi-fuel-pump me-1" viewBox="0 0 16 16">
          <path d="M3 2.5a.5.5 0 0 1 .5-.5h5a.5.5 0 0 1 .5.5v5a.5.5 0 0 1-.5.5h-5a.5.5 0 0 1-.5-.5z"/>
          <path d="M1 2a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v8a2 2 0 0 1 2 2v.5a.5.5 0 0 0 1 0V8h-.5a.5.5 0 0 1-.5-.5V4.375a.5.5 0 0 1 .5-.5h1.495c-.011-.476-.053-.894-.201-1.25a2 2 0 0 0-.394-.569.5.5 0 0 1 .707-.707 3 3 0 0 1 .592.862c.217.428.301 1.01.301 1.664v7.127a1.5 1.5 0 0 1-3 0V10a1 1 0 0 0-1-1v5.5a.5.5 0 0 1-1 0V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v13h6.5a.5.5 0 0 1 0 1H.5a.5.5 0 0 1 0-1H1z"/>
        </svg>
        : {{ total_transactions }}
      </button>
      <global-search-field
        v-model:filterValue="filter"
      />
      <div class="d-flex justify-content-end mb-3">
        <button 
                                class="btn btn-primary refresh-btn rounded-circle p-2 me-2 spin-animation" 
                                @click="getAssetBincard()" 
                                title="Refresh page"
                                :disabled="loading || loading_spinner"
                                style="width: 2.5rem; height: 2.5rem;"
                            >
                            <span v-if="loading || loading_spinner" v-html="loadingSpinner()">

                            </span>
                                <svg 
                                    xmlns="http://www.w3.org/2000/svg" 
                                    width="16" 
                                    height="16" 
                                    fill="currentColor" 
                                    class="bi bi-arrow-clockwise" 
                                    viewBox="0 0 16 16"
                                >
                                    <path fill-rule="evenodd" d="M8 3a5 5 0 1 0 4.546 2.914.5.5 0 0 1 .908-.417A6 6 0 1 1 8 2v1z"/>
                                    <path d="M8 4.466V.534a.25.25 0 0 1 .41-.192l2.36 1.966c.12.1.12.284 0 .384L8.41 4.658A.25.25 0 0 1 8 4.466z"/>
                                </svg>
                            </button>
        <button class="btn btn-primary me-2" @click="asset_bincard = !asset_bincard" v-if="user_permissions.includes('can_register_asset_bincard') && selectedBudget">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16"> 
            <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/> 
            <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/> 
          </svg>
        </button>
              <button class="btn btn-outline-primary"
                data-bs-toggle="offcanvas"
                data-bs-target="#offcanvasWithBothOptions">
     Select Project
        </button>
      </div>

    </div>

  

     <!-- No Records Message -->
    <div v-if="selectedProject && filteredData.length === 0" class="text-center my-4">
      <p class="mb-0">No records found for {{ selectedProject.short_name }} {{ selectedBudget?.name }}</p>
    </div>
    
    <div v-if="!selectedBudget" class="text-center my-4">
      <p class="mb-0">Please select a budget from the project list</p>
    </div>
  
   <div class="d-flex justify-content-start mb-3" v-if="ShowAssetDiv">
  <div class="card" ref="assetDivRef">
  <div class="card-body">
    <h8 class="card-title text-center text-dark">Assets Filled Today</h8>
    <div v-for="(asset, index) in assets_counts" 
               :key="asset.id" 
               class="list-group-item list-group-item-action d-flex align-items-center">
            <span class="badge bg-secondary rounded-pill me-3">{{ index + 1 }}</span>
            <span class="fw-bold">{{ asset.name }} - {{ asset.type_name }}</span>
          </div>
  </div>
</div>
</div>


    <div class="offcanvas offcanvas-end" data-bs-scroll="true" tabindex="-1"
         id="offcanvasWithBothOptions">
      <div class="offcanvas-header">
        <h5 class="offcanvas-title">PROJECT LISTS</h5>
        <button type="button" class="btn-close" data-bs-dismiss="offcanvas"></button>
      </div>

      <div class="offcanvas-body">
        <div class="row">
          <div class="col-12">
            <div class="list-group" id="list-tab" role="tablist">
              <span v-if="loading_spinner" v-html="waitIndicator()"></span>

              <div v-for="project in projects" :key="project.id" class="mb-1">
                <div 
                  class="list-group-item d-flex justify-content-between align-items-center"
                  :class="{ active: selectedProject && selectedProject.id === project.id && selectedBudget }"
                  @click="toggleProject(project)"
                  style="cursor:pointer"
                >
                  {{ project.short_name }}
                  <i 
                    class="bi"
                    :class="openedProjectId === project.id ? 'bi-chevron-up' : 'bi-chevron-down'"
                  ></i>
                </div>

                <div v-if="openedProjectId === project.id" class="ms-3 mt-1 bg-light">
                  <div v-if="isBudgetsloading" class="text-muted small">
                    <span v-html="waitIndicator()"></span>
                  </div>

                  <div 
                    v-for="b in budgets" 
                    :key="b.id"
                    class="list-group-item list-group-item-action list-group-item-budget"
                    :class="{ active: selectedBudget && selectedBudget.id === b.id }"
                    @click="selectBudget(project, b)"
                    data-bs-dismiss="offcanvas"
                  >
                    {{ b.name }} 
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

   

    <div class="my-4">
      <!-- item registration form starts -->
      <form v-if="asset_bincard" class="mt-3 p-3 border rounded bg-white shadow" @submit.prevent="registerBinCard">
        <h4 class="text-center">REGISTER BIN CARD</h4>
        <div class="row mb-2">
          <div class="col-md-6">
            <label class="form-label">Select Asset</label>
            <Multiselect 
              v-model="asset"
              :options="assets" 
              label="name"  
              track-by="id" 
              placeholder="Select An Asset"
              :searchable="true"
              :close-on-select="true"
              required
            />
          </div>
        </div>
        <div class="text-center gap-2 justify-content-end">
          <button type="button" class="btn btn-danger me-3" @click="asset_bincard = false; resetForm();">Cancel</button>
          <button type="submit" class="btn btn-primary" :disabled="loading">
            <span v-if="loading" class="spinner-border spinner-border-sm me-1" role="status" aria-hidden="true"></span>
            <span v-else>Register</span>
          </button>
        </div>
      </form>
      <!-- item registration form ends-->
    </div>
    
    <!-- loading spinner starts -->
    <div v-if="loading_spinner" v-html="waitIndicator()"></div>
    <!-- Loading spinner ends -->


    <!-- Bin Cards List -->
    <div v-else class="accordion accordion-flush" id="accordionFlushExample">
      <div class="accordion-item" v-for="(card, index) in filteredData" :key="card.id">
        <h2 class="accordion-header">
          <button 
            class="accordion-button collapsed" 
            type="button"
            data-bs-toggle="collapse"
            :data-bs-target="'#flush-collapse-' + index"
            aria-expanded="false"
            :aria-controls="'flush-collapse-' + index"
          >
            <div class="d-flex w-100 justify-content-between align-items-center">
              <!-- Left side content -->
              <div class="d-flex flex-wrap">
                <span>{{ card?.asset }}</span>&nbsp;&nbsp;&nbsp;
                <span>Consumption Type: {{ card?.consuption_type || '--' }}</span>&nbsp;&nbsp;&nbsp;
                <span>Balance: {{ Number(card.balance).toLocaleString() }} ltrs</span>
              </div>

              <!-- Right side content with budget name and delete icon -->
              <div class="d-flex align-items-center gap-2">
                <span class="fw-bold">{{ card.budget?.name }} {{ Number(card.bincard_increments).toLocaleString() }} LTs</span>
                <a
                  href="javascript:;"
                  class="text-danger me-3"
                  @click="deleteBinCard(card)"
                  v-if="user_permissions.includes('can_delete_asset_bincard')"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" class="bi bi-trash" viewBox="0 0 16 16">
                    <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                    <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
                  </svg>
                </a>
              </div>
            </div>
          </button>
        </h2>
        
        <div :id="'flush-collapse-' + index" class="accordion-collapse collapse" data-bs-parent="#accordionFlushExample">
          <div class="accordion-body">
            <div class="d-flex justify-content-end mb-3">  
              <button 
                class="btn btn-primary" 
                data-bs-toggle="modal" 
                data-bs-target="#add-item-modal" 
                @click="openAddTransactionModal(card)"  
                v-if="user_permissions.includes('can_register_asset_bincard')"
              > 
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-plus-square" viewBox="0 0 16 16">
                  <path d="M14 1a1 1 0 0 1 1 1v12a1 1 0 0 1-1 1H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1zM2 0a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V2a2 2 0 0 0-2-2z"/>
                  <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4"/>
                </svg>
              </button>
              <button class="btn btn-success ms-2" @click="printBinCard(card.asset_id)">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-printer" viewBox="0 0 16 16">
                  <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1"/>
                  <path d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"/>
                </svg>
              </button>
            </div> 

            <div class="panel p-0 mt-3">   
              <div class="row layout-top-spacing">
                <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                  <div class="panel p-0">
                    <div class="custom-table table3">
                      <div class="table-responsive">
                        <table class="table table-striped table-hover align-middle">
                          <thead class="table-dark">
                            <tr>
                              <th>Sno</th>
                              <th>Date</th>
                              <th>Action</th>
                              <th>Quantity</th>
                              <th>Task</th>
                              <th>Initial Reading</th>
                              <th>Final Reading</th>
                              <th>Expected Ratio</th>
                              <th>Work Target</th>
                              <th>Work Covered</th>
                              <th>Balance</th>
                              <th>Cost</th>
                              <th class="text-center">Actions</th>
                            </tr>
                          </thead>
                          <tbody>
                            <template v-for="(transaction, index) in card.transactions" :key="transaction.id">
                            <tr v-if="transaction.asset">
                                <td colspan="1"></td>
                                <td v-if="card.asset_id == 0" colspan="3" class="bg-white text-dark fw-bold">
                                  <strong>Asset :</strong> {{ transaction?.asset?.name }} {{ transaction?.asset?.type_name }} 
                                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" fill="currentColor" class="bi bi-arrow-90deg-down fw-bold" viewBox="0 0 16 16" transform="scale(-1 1) translate(-16 0)">
  <path fill-rule="evenodd" d="M4.854 14.854a.5.5 0 0 1-.708 0l-4-4a.5.5 0 0 1 .708-.708L4 13.293V3.5A2.5 2.5 0 0 1 6.5 1h8a.5.5 0 0 1 0 1h-8A1.5 1.5 0 0 0 5 3.5v9.793l3.146-3.147a.5.5 0 0 1 .708.708z"/>
</svg>
                                </td>
                              </tr>
                              <tr>
                                <td @click="showMessage(transaction.id)">{{ index + 1 }}</td>
                                <td>{{ transaction.date }}</td>
                                <td>{{ transaction.action }}</td>
                                <td>{{ transaction.quantity }} ltrs</td>
                                <td>{{ transaction.task }}</td>
                                <td>{{ transaction.initial_reading }}</td>
                                <td>{{ transaction.final_reading }}</td>
                                <td>{{ transaction?.ratio ?? '---' }} </td>
                                <td>{{ transaction.work_target }} {{ transaction.unit }}</td>
                                <td>{{ transaction.work_covered ?? 0 }} {{ transaction.unit }}</td>
                                <td>{{ transaction.balance }} ltrs</td>
                                <td>{{ formatNumber(transaction.rate * transaction.quantity) }}</td>
                                <td class="text-center ">
                                  <div class="btn-group">
                                  <a
                                    href="javascript:;"
                                    class="edit me-2"
                                    @click="openEditModal(transaction)"
                                    data-bs-toggle="modal"
                                    data-bs-target="#edit-transaction-modal"
                                    v-if="user_permissions.includes('can_edit_asset_bincard_transactions')"
                                  >
                                    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-eye text-primary" viewBox="0 0 16 16">
                                      <path d="M16 8s-3-5.5-8-5.5S0 8 0 8s3 5.5 8 5.5S16 8 16 8M1.173 8a13 13 0 0 1 1.66-2.043C4.12 4.668 5.88 3.5 8 3.5s3.879 1.168 5.168 2.457A13 13 0 0 1 14.828 8q-.086.13-.195.288c-.335.48-.83 1.12-1.465 1.755C11.879 11.332 10.119 12.5 8 12.5s-3.879-1.168-5.168-2.457A13 13 0 0 1 1.172 8z"/>
                                      <path d="M8 5.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5M4.5 8a3.5 3.5 0 1 1 7 0 3.5 3.5 0 0 1-7 0"/>
                                    </svg>
                                  </a>
                                    <a
                  href="javascript:;"
                  class="text-danger me-3"
                  @click.stop="deleteBinCardTransaction(transaction)"
                  v-if="user_permissions.includes('can_delete_asset_bincard')"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" fill="currentColor" class="bi bi-trash" viewBox="0 0 16 16">
                    <path d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"/>
                    <path d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"/>
                  </svg>
                </a>
                                  </div>

                                </td>
                              </tr>
                              <tr v-if="transaction.description ">
                                <td colspan="1"></td>
                                <td  colspan="8" class="bg-white text-danger">
                                  <strong>Remark:</strong> <i>{{ transaction?.description }}</i>
                                </td>
                              </tr>
                            </template>
                          </tbody>
                        </table>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- add transaction starts -->
    <div class="modal fade mymodal" id="add-item-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="itemModalLabel" aria-hidden="true">
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="itemModalLabel">Create Bin Card Transaction for {{ selectedCard?.asset }}</h1>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close" @click="closebinCardModal()" id="close_item"></button>
          </div>
          <form @submit.prevent="addTransaction()">
            <div class="modal-body">
              <div class="row mb-3">
                <div class="col-md-3">
                  <label for="direction">Transaction Type</label>
                  <Multiselect
                    v-model="direction"
                    :options="directions"
                    label="label"
                    track-by="value"
                    placeholder="Select Direction"
                    :searchable="true"
                    :allow-empty="false"
                    required
                  />
                </div>
                <div class="col-md-3">
                  <label for="quantity">Quantity</label>
                  <input type="number" v-model="quantity" class="form-control" placeholder="Enter Quantity" step="any">
                </div>
                <div class="col-md-3">
                  <label for="date">Date</label>
                  <input type="date" v-model="date" class="form-control">
                </div>
                <div class="col-md-3" >
                  <label for="ratio">Ratio</label>
                  <input type="number" v-model="ratio" class="form-control" placeholder="Enter Ratio" required step="any">
                </div>

                <div class="col-md-3" >
                  <label for="initial_reading">Initial ordometer Reading</label>
                  <input type="number" v-model="initial_reading" class="form-control" placeholder="Enter Initial Reading" required step="any">
                </div>

                <div class="col-md-3">
                  <label for="work_target">Work Target</label>
                  <input type="number" v-model="work_target" class="form-control" placeholder="Enter Work Target" step="any">
                </div>
                                <div class="col-md-3">
                  <label for="unit">Work Unit</label>
                  <Multiselect
                    v-model="unit"
                    :options="units"
                    label="short_name"
                    track-by="id"
                    placeholder="Select Unit"
                    :searchable="true"
                    :allow-empty="false"
                    required
                  />
                </div>
                <div class="col-md-3">
                  <label for="work_target">Fuel rate</label>
                  <input type="number" v-model="rate" class="form-control" placeholder="Enter Rate" step="any">
                </div>


                                <div class="col-md-4"
                                v-if="selectedCard?.asset_id === 0"
                                >
                  <label for="task">Select Asset</label>
  <Multiselect 
              v-model="asset"
              :options="assets" 
              label="name"  
              track-by="id" 
              placeholder="Select An Asset"
              :searchable="true"
              :close-on-select="true"
              required
            />
                </div>
                <div class="col-md-8">
                  <label for="task">Task</label>
                  <input type="text" v-model="task" class="form-control" placeholder="Enter Task">
                </div>

                <div class="col-md-12">
                  <label for="description">Remark</label>
                  <input type="text" v-model="description" class="form-control" placeholder="Enter Any Remark concerning work or ratio valiation">
                </div>
              </div>
            </div>
            <div class="modal-footer">
              <button type="button" class="btn btn-danger" data-bs-dismiss="modal" @click="closebinCardModal()" id="close_item">Close</button>
              <button class="btn btn-primary me-2 mt-1" :disabled="isSending">
                <span v-if="isSending" v-html="loadingSpinner()"></span>
                <span>Save</span>
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
    <!-- add transaction ends -->

    <!-- Edit bin card item modal starts -->
    <div class="modal fade mymodal" id="edit-transaction-modal" data-bs-backdrop="false" data-bs-keyboard="false" tabindex="-1" aria-labelledby="editTransactionModalLabel" aria-hidden="true">
      <div class="modal-dialog modal-xl">
        <div class="modal-content">
          <div class="modal-header">
            <h1 class="modal-title fs-5" id="editTransactionModalLabel"> {{ selectedCard?.asset }} Bin Card Transaction</h1>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <form @submit.prevent="updateBinCardTransaction()">
            <div class="modal-body">
              <div class="row mb-3">
                <div class="col-md-4">
                  <label for="initial_reading">Initial Ordometer Reading</label>
                  <input type="number" v-model="initial_reading" class="form-control" placeholder="Enter Initial Reading" step="any" >
                </div>
                <div class="col-md-4">
                  <label for="final_reading">Final Ordometer Reading</label>
                  <input type="number" v-model="final_reading" class="form-control" placeholder="Enter Final Reading" step="any" >
                </div>
                <div class="col-md-4">
                  <label for="work_covered">Work Covered</label>
                  <input type="number" v-model="work_covered" class="form-control" placeholder="Enter Work Covered" step="any">
                </div>

                  <div class="col-md-4" v-if="user_permissions.includes('is_programmer')">
                   <label for="direction">Transaction Type</label>
                  <Multiselect
                    v-model="direction"
                    :options="directions"
                    label="label"
