    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const tableShimmer = inject('tableShimmer');JSON.parse(localStorage.getItem("user"))
    const loadingSpinner = inject('loadingSpinner'); 
    const formatNumber = inject('formatNumber');
    const asset_bincard = ref(false);
    const selectedProject = ref(null)

    const loading_spinner = ref(false);
    const transactionColumns = ref(['SNo', 'date','action','quantity','task','initial','final','ratio','work_target','work_covered','balance','cost','actions']);
    const binCards = ref([]);
