  const filteredData = computed(() => {
    let data = globalSearch(binCards.value, filter.value);

    if (selectedProject.value) {
        data = data.filter(card => 
            card.project_id === selectedProject.value.id
        );
    }

    return data;
});


    const table_option = ref({
        perPage: 20,
