            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

  const directions = ref([
        { label: 'Bulk Receiving', value: 'INCREMENT' },
        { label: 'Issue from Bulk',   value: 'DECREMENT' },
        { label: 'Direct Issuing',   value: 'NEUTRAL' }
    ]);
 
  
const getAssetBincard = async (showLoading = true) => {
  if (showLoading) loading_spinner.value = true;
  if (showLoading) binCards.value = [];

  try {
    let url = `get-asset-bincards?project_id=${selectedProject.value.id}`;

    // Only append budget_id if a real budget is selected (not 'all')
    if (selectedBudget.value && selectedBudget.value.id !== 'all') {
      url += `&budget_id=${selectedBudget.value.id}`;
    }

    const response = await axiosInstance.get(url);

    binCards.value = response.data.map((item, index) => ({
      ...item,
      SNo: index + 1,
      consuption_type: item?.asset?.consuption_type ?? '',
      asset: (item?.asset?.name ?? 'BULK FUEL')+' - ' + (item?.asset?.type_name ?? ''),
      balance: parseFloat(item.balance).toFixed(2),
      transactions: item.transactions.map((tx, tIndex) => ({
        ...tx,
        SNo: tIndex + 1,
        ref_no: tx.id,
        direction: tx.direction,
        quantity: tx.quantity,
        date: tx.date,
        initial_reading: tx.initial_reading ,
        final_reading: tx.final_reading ,
        task: tx.task,
        ratio: (tx?.ratio ?? '---') + ' ' + (item?.asset?.consuption_type ?? ''),
        asset : tx?.asset ?? '',
        work_target: tx.work_target,
        work_covered: tx.work_covered,
        balance: parseFloat(tx.balance).toFixed(2),
        remark: tx.remark || '-'
      }))
    }));

  } catch (error) {
    showError(error.message);
  } finally {
    if (showLoading) loading_spinner.value = false;
  }
};



    const loading = ref(false);
    const registerBinCard = async () => {
        loading.value = true;
        
        const existingBinCard = binCards.value.find(card => 
            card.asset_id === asset.value.id && 
            card.project_id === selectedProject.value.id
        );
        if (existingBinCard) {
            showError('This asset already has a bin card registered for this project!');
            loading.value = false;
            return;
        }
        
const payload = {
    asset_id: asset.value.id,
    project_id: selectedProject.value.id,
    registrar_id: JSON.parse(localStorage.getItem("user")).id,
    description: description.value,
    remark: remark.value,
    ...(selectedBudget?.value?.id !== 'all' && { budget_id: selectedBudget.value.id })
};


        try {
            const response = await axiosInstance.post('asset-bincards', payload);
            getAssetBincard(false);
            showMessage('Record registered successfully!');
            resetForm();
        } catch (error) {
          console.log(error);
            showError(error.message);
        } finally {
            loading.value = false;
        }
    };

    const resetForm = () => {
   asset_bincard.value = false;
   description.value = ''
   remark.value = '',
   asset.value = ''
};

const selectedCard = ref(null);
const openAddTransactionModal = (card) => {
    selectedCard.value = card;
};

const direction = ref('');
const quantity = ref('');
const rate = ref('');
const task = ref('');
const initial_reading = ref('');
const ratio = ref('');
const description = ref('');
const final_reading = ref('');
const work_target = ref('');
const work_covered = ref('');
const remark = ref('');
const isSending = ref(false);
const date = ref('');


const addTransaction = async () => {
    isSending.value = true;
    const payload = {
        asset_bincard_id: selectedCard.value.id,
        asset_id : asset.value.id ?? '' ,
        date: date.value,
        direction: direction.value.value,
        quantity: quantity.value,
        rate: rate.value,
        registrar_id: JSON.parse(localStorage.getItem("user")).id,
        task: task.value,
        initial_reading: initial_reading.value,
        final_reading: final_reading.value,
        unit: unit.value.short_name,
        ratio: ratio.value,
        work_target: work_target.value,
        work_covered: work_covered.value,
        description: description.value,
        action: direction.value.label,
        remark: remark.value
    };

    try {
        const response = await axiosInstance.post('asset-bincard-transactions', payload);
        getAssetBincard(false);
        showMessage('Transaction added successfully!');
        document.getElementById('close_item').click();
        closebinCardModal();
    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        isSending.value = false;
    }
};

const closebinCardModal = () => {
    direction.value = '';
    quantity.value = '';
    rate.value = '';
    date.value = '';
    task.value = '';
    initial_reading.value = '';
    final_reading.value = '';
    ratio.value = '';
    work_target.value = '';
    work_covered.value = '';
    description.value = '';
    remark.value = '';
};


const assets = ref([])
const asset = ref('')
const getAssets = async () => {
   try{
      const response = await axiosInstance.get('machines')
        assets.value = [
            { id: 0, name: "BULK FUEL" },
            ...response.data.map((item)=>({
        ...item,
        name : item.name + ' '+ item.type_name
      })),
        ]
   }catch(error){
    showError(error.message)
    console.log(error)
   }finally{

   }
};

const editId = ref(null);
const openEditModal = (row) => {
    initial_reading.value = row.initial_reading;
    final_reading.value = row.final_reading;
    work_covered.value = row.work_covered;
    editId.value = row.id;
};

const updateBinCardTransaction = async () => {
    isSending.value = true; 
const payload = {
    initial_reading: initial_reading.value ?? '',
    final_reading: final_reading.value ?? '',
    work_covered: work_covered.value,
    ...(direction?.value?.value && { 
      direction: direction.value.value ,
      action : direction.value.label 
    }),

      ...(asset?.value?.id && { 
      asset_id: asset.value.id
    }),

      ...(description?.value && { 
      description : description.value
    })

};

    try {
        const response = await axiosInstance.put(`asset-bincard-transactions/${editId.value}`, payload);
        getAssetBincard(false);
        showMessage('Transaction updated successfully!');
        document.getElementById('close_transaction_editing').click();
    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        isSending.value = false;
    }
};

 const units = ref([])
 const unit = ref('')
const getUnits = async () => {
  try {
    const response = await axiosInstance.get('units');
    units.value = response.data;
  } catch (error) {
    console.log(error);
    showError(error.message);
  }
};

  const project = ref('')
 const projects = ref([])
 const getProjects = async () => {
    try {
        const response = await axiosInstance.get('projects');
        projects.value = response.data
            .filter(item => item.contracted === 'YES')
            .filter(item => item.status === 'active');
    } catch (error) {
        showError(error.message);
    }
};

const budgets = ref([])
const isBudgetsloading = ref(false)

const getBudgets = async (id) => {
  isBudgetsloading.value = true;
  budgets.value = [{ id: 'all', name: 'ALL DATA' }];

  try {
    const response = await axiosInstance.get(`get-budgets?project_id=${id}`);
    const realBudgets = response.data.filter(b => b.status === "closed");
    budgets.value = [...budgets.value, ...realBudgets];
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    isBudgetsloading.value = false;
  }
};



const openedProjectId = ref(null);

const toggleProject = async (project) => {
  if (openedProjectId.value === project.id) {
    openedProjectId.value = null;
    budgets.value = [];
  } else {
    openedProjectId.value = project.id;
    await getBudgets(project.id);
  }
};

const selectedBudget = ref(null);

const selectBudget = async (project, b) => {
  selectedProject.value = project;
  selectedBudget.value = b;

  await getAssetBincard();

};

const assets_counts = ref([]);
const total_transactions = ref(0);
const getAssetsCounts = async () => {
  try {
    const { data } = await axiosInstance.get('todays-asset-usage');

    total_transactions.value = data.count;

    assets_counts.value = data.assets.map((item, index) => ({
      ...item,
      SNo: index + 1,
    }));

  } catch (error) {
    console.log(error);
    showError(error.message);
  }
};

    onMounted(() => {
        getAssets()
        getProjects()
        getUnits()
        getAssetsCounts()

        document.addEventListener('click', handleClickOutside);
    
        const offcanvasElement = document.getElementById('offcanvasWithBothOptions');
  if (offcanvasElement) {
    const offcanvas = new bootstrap.Offcanvas(offcanvasElement);
    offcanvas.show();
  }
    });



const showConfirmation = inject('showConfirmation');
const deleteBinCard = async (card) => {
  try {
    const res = await showConfirmation(
      'Delete Bin Card',
      `Are you sure you want to delete bin card for ${card.asset}?`,
      `asset-bincards/${card.id}?deleted=1`,
      'put'
    );

    if (res?.refresh) {
      getAssetBincard(false);
    }

  } catch (error) {
    console.error(error);
    showError(error.message);
  } 
}

const deleteBinCardTransaction = async (transaction) => {
  try {
    const res = await showConfirmation(
      'Delete Bin Card Transaction',
      `Are you sure you want to delete transaction with  ${transaction.quantity} Ltrs ?`,
      `asset-bincard-transactions/${transaction.id}?deleted=1`,
      'put'
    );

    if (res?.refresh) {
      getAssetBincard(false);
    }

  } catch (error) {
    console.error(error);
    showError(error.message);
  } 
}

const handleClickOutside = (event) => {
  if (
    ShowAssetDiv.value &&
    assetDivRef.value &&
    !assetDivRef.value.contains(event.target)
  ) {
    ShowAssetDiv.value = false;
  }
};

onBeforeUnmount(() => {
  document.removeEventListener('click', handleClickOutside);
});

</script>
